def render_upper(template):
    parts = []
    for item in template:
        if isinstance(item, str):
            parts.append(item)
        else:
            parts.append(str(item.value).upper())
    return ''.join(parts)

def sql_safe(template):
    parts = []
    params = []
    for item in template:
        if isinstance(item, str):
            parts.append(item)
        else:
            parts.append('?')
            params.append(item.value)
    return ''.join(parts), tuple(params)
